// Read input
const fs = require('fs');
const parts = fs.readFileSync(0, 'utf-8').trim().split(/\s+/).map(Number);
const n = parts[0], target = parts[1];
const arr = parts.slice(2, 2 + n);

const map = new Map();
for (let i = 0; i < n; i++) {
  const need = target - arr[i];
  if (map.has(need)) {
    console.log(map.get(need) + 1, i + 1);
    process.exit(0);
  }
  if (!map.has(arr[i])) map.set(arr[i], i);
}
console.log(-1);

codeSnippets.PYTHON:
import sys
data = list(map(int, sys.stdin.read().strip().split()))
if not data: 
    print(-1); sys.exit()
n, target = data[0], data[1]
arr = data[2:2+n]
seen = {}
for i, v in enumerate(arr):
    need = target - v
    if need in seen:
        print(seen[need] + 1, i + 1)
        sys.exit(0)
    if v not in seen:
        seen[v] = i
print(-1)

